window.kbPageData["cards/d39717a3c184d8d0d152bf26"] = {"qs":{"政治理论必刷100题#85":{"paper":"政治理论必刷100题","n":85,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",26],"asrc":["国省考政治理论必刷100题.pdf",87],"m":[],"task":"核对管党治党责任、党性党风党纪一起抓、风腐同查同治和以案促改促治的要求，识别用语不准确的一项。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答依据是管党治党和风腐治理的政策要求，考察行程与全会日期只提供出处。"},"links":[{"id":"k-259e0b87a97a8b62","label":"党性党风党纪一起抓","catalog_id":"73010ca4730714f9","type":"制度与规则","role":"直接考查","field":"answer","quote":"持党性党风党纪一起抓、正风肃纪反腐相贯通","why":"准确识别一起抓的三个方面即可定位用语错误。","origin":"逐题标记"},{"id":"k-22b35f1b6c6a78e3","label":"领导干部履行管党治党责任并以自身模范行动净化政治生态","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"各级领导干部要切实履行管党治党责任，作风正派、公道处事","why":"题目核对领导干部履责和推动政治生态持续净化的要求。","origin":"逐题标记"},{"id":"k-df86a6532824ef9d","label":"风腐同查严惩交织问题、同治铲除共性根源","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"以“同查”严惩风腐交织问题，以“同治”铲除风腐共性根源","why":"题目核对风腐同查与同治各自对应的治理目标。","origin":"逐题标记"},{"id":"k-1f5a2ec1f3c9f176","label":"以案促改促治要求完善权力运行监督并健全新型腐败和隐性腐败防治办法","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"增强以案促改促治实效，推动完善权力配置运行的制约和监督机制","why":"题目核对以案促改促治在权力监督和腐败防治方面的配套要求。","origin":"逐题标记"}],"stem":"中央八项规定既不是最高标准，更不是最终目的，只是我们改进作风的第一步，是\n\n我们作为共产党人应该做到的基本要求。以下有关党的建设的表述，不准确的是（      ）。","options":["各级领导干部要切实履行管党治党责任，作风正派、公道处事，以自身模范行动推动\n\n政治生态持续净化","要坚持党规党纪党务一起抓、正风肃纪反腐相贯通，在铲除腐败滋生的土壤和条件上\n\n常抓不懈","以“同查”严惩风腐交织问题，以“同治”铲除风腐共性根源","增强以案促改促治实效，推动完善权力配置运行的制约和监督机制，丰富防治新型腐\n\n败和隐性腐败有效办法"],"answer":"B","analysis":"85.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，2025 年 3 月 19 日至 20 日，习近平总书记在云南考察时的讲话指出：“党的\n\n领导是事业发展的根本保证。看一个地方党的领导和党的建设水平高不高，一个重要方面就\n\n是看政治生态好不好。各级领导干部要切实履行管党治党责任，作风正派、公道处事，以自\n\n身模范行动推动政治生态持续净化。”\n\n  B 项错误，2025 年 3 月 17 日至 18 日，习近平总书记在贵州考察时的讲话指出：“要坚\n\n持党性党风党纪一起抓、正风肃纪反腐相贯通，在铲除腐败滋生的土壤和条件上常抓不懈。”\n\n故“党规党纪党务”表述错误，应为“党性党风党纪”。\n\n  C、D 两项正确，2025 年 1 月 6 日，习近平总书记在二十届中央纪委四次全会上的讲话\n\n指出：“增强以案促改促治实效，推动完善权力配置运行的制约和监督机制，丰富防治新型\n\n腐败和隐性腐败有效办法。坚持正风肃纪反腐相贯通，以‘同查’严惩风腐交织问题，以‘同\n\n治’铲除风腐共性根源。”\n\n  本题为选非题，故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false},"政治理论必刷100题#86":{"paper":"政治理论必刷100题","n":86,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",26],"asrc":["国省考政治理论必刷100题.pdf",87],"m":[],"task":"辨别从严监督执纪中的监督合力、监督前哨、严管厚爱和风腐同查同治要求，找出表述有误的一项。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答依据是监督执纪的制度要求，相关会议只提供表述出处。"},"links":[{"id":"k-a460727ca8a3699e","label":"党内监督与人民监督相结合，发挥群众监督和舆论监督的前哨作用","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"要把党内监督和人民监督结合起来，重视发挥群众监督、舆论监督‘前哨’","why":"承担前哨作用的监督方式决定了选非判断。","origin":"逐题标记"},{"id":"k-cbc9e0669b3200e8","label":"完善党和国家监督制度，形成全面覆盖、常态长效的监督合力","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"坚持完善党和国家监督制度，形成全面覆盖、常态长效的监督合力。","why":"题目核对党和国家监督制度在覆盖范围与运行常态化方面的要求。","origin":"逐题标记"},{"id":"k-16f3b707864928dd","label":"严管厚爱相结合并落实三个区分开来以激励干部担当","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"坚持严管和厚爱相结合，落实“三个区分开来”，激励干部敢于担当、积极作为","why":"题目核对干部管理中结合严格监督与担当激励的要求。","origin":"逐题标记"},{"id":"k-df86a6532824ef9d","label":"风腐同查严惩交织问题、同治铲除共性根源","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"以‘同查’严惩风腐交织问题","why":"题目核对同查针对交织问题、同治针对共性根源的分工。","origin":"逐题标记"}],"stem":"习近平总书记强调，“从严监督执纪是党的自我革命的利器，对违纪违法问题必须\n\n坚决处理。”下列关于从严监督执纪的表述，不正确的是（           ）。","options":["要坚持完善党和国家监督制度，形成全面覆盖、常态长效的监督合力","要把党内监督和人民监督结合起来，重视发挥司法监督“前哨”作用","要坚持严管和厚爱相结合，落实“三个区分开来”，激励干部敢于担当、积极作为","要坚持正风肃纪反腐相贯通，以“同查”严惩风腐交织问题，以“同治”铲除风腐共\n\n性根源"],"answer":"B","analysis":"86.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，2022 年 1 月 18 日，习近平总书记在十九届中央纪委六次全会上的讲话中提\n\n到：“坚持完善党和国家监督制度，形成全面覆盖、常态长效的监督合力。”\n\n  B 项错误，2025 年 6 月 30 日，习近平总书记在中共中央政治局第二十一次集体学习时\n\n的讲话中提到：“要把党内监督和人民监督结合起来，重视发挥群众监督、舆论监督‘前哨’\n\n作用，推动各类监督贯通协调。”故“发挥司法监督‘前哨’作用”说法错误，应是“发挥\n\n群众监督、舆论监督‘前哨’作用”。\n\n  C 项正确，2022 年 10 月 16 日，习近平总书记在中国共产党第二十次全国代表大会上的\n\n报告中提到：“坚持严管和厚爱相结合，加强对干部全方位管理和经常性监督，落实‘三个\n\n区分开来’，激励干部敢于担当、积极作为。”\n\n  D 项正确，2025 年 1 月 6 日，习近平总书记在二十届中央纪委四次全会上的讲话中提到：\n\n“坚持正风肃纪反腐相贯通，以‘同查’严惩风腐交织问题，以‘同治’铲除风腐共性根\n\n源。”\n\n  本题为选非题，故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false},"政治理论必刷100题#87":{"paper":"政治理论必刷100题","n":87,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",27],"asrc":["国省考政治理论必刷100题.pdf",88],"m":[],"task":"判断军队党的建设与战斗力的关系、党的力量来源及选人用人和人才改革的表述，找出有误的一项。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答依据是军队党的建设和人才工作的原则，述评发表时间只提供出处。"},"links":[{"id":"k-522c911507a1db27","label":"党的力量来自组织，组织强则军队强","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"党的力量来自组织，组织强则军队强。","why":"题目要求准确识别党的力量来源及组织建设对军队建设的作用方向。","origin":"逐题标记"},{"id":"k-b2e8968d79ac7287","label":"军队党的建设围绕能打仗、打胜仗展开","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"军队党的建设必须紧紧围绕能打仗、打胜仗来展开","why":"题目核对军队党的建设以战斗力为导向的要求。","origin":"逐题标记"},{"id":"k-9ebda3c13218d4b5","label":"选人用人对干部队伍建设具有导向作用并反映政治生态","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"选人用人是干部队伍建设的指挥棒，是政治生态的风向标。","why":"题目核对选人用人在干部队伍建设和政治生态中的作用。","origin":"逐题标记"},{"id":"k-f0fe2b99668b4de3","label":"以改革创新激发军队人才队伍的动力活力","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"坚持改革创新，深层激发人才队伍动力活力。","why":"题目核对军队人才队伍建设的改革要求。","origin":"逐题标记"}],"stem":"党的领导和党的建设是我军建设发展的关键，关系强军事业兴衰成败，关系党和国\n\n家长治久安，下列相关表述有误的一项是（       ）。","options":["军队党的建设必须紧紧围绕能打仗、打胜仗来展开","党的力量来自军队，军队强则组织强","选人用人是干部队伍建设的指挥棒，是政治生态的风向标","坚持改革创新，深层激发人才队伍动力活力"],"answer":"B","analysis":"87.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2023 年 7 月，新华社发表名为《在党的旗帜下奋斗强军——以习近平同志为核心的党\n\n中央领导推进新时代人民军队党的领导和党的建设述评》的重要文章（以下简称文章）。\n\n  A 项正确，文章指出，军队党的建设必须紧紧围绕能打仗、打胜仗来展开，成为部队战\n\n斗力的增强剂和功放器。人民军队牢固树立战斗力这个唯一的根本的标准，现代化水平和实\n\n战能力显著提升。\n\n  B 项错误，文章指出，党的力量来自组织，组织强则军队强。人民军队各级党组织领导\n\n力、组织力、执行力不断增强，强军兴军的特有优势持续强固。\n\n  C 项正确，文章指出，选人用人是干部队伍建设的指挥棒，是政治生态的风向标。中央\n\n军委成立人才工作领导小组、干部考评委员会，全方位考察识别、大范围交流使用干部，接\n\n续深化干部工作大检查，匡正选人用人风气，纯洁高级干部队伍。\n\n  D 项正确，文章指出，坚持改革创新，深层激发人才队伍动力活力。人员结构布局深度\n\n优化。大幅压减全军团级以上机关现役员额，精简服务保障等机构和人员。\n\n  本题为选非题，故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","军事"],"nature":"知识题","current":false}},"materialFiles":{},"terms":{"k-259e0b87a97a8b62":{"id":"k-259e0b87a97a8b62","mode":"k","type":"制度与规则","title":"党性党风党纪一起抓","qs":[],"count":1},"k-22b35f1b6c6a78e3":{"id":"k-22b35f1b6c6a78e3","mode":"k","type":"制度与规则","title":"领导干部的管党治党责任","qs":[],"count":1},"k-df86a6532824ef9d":{"id":"k-df86a6532824ef9d","mode":"k","type":"制度与规则","title":"风腐同查同治","qs":[],"count":2},"k-1f5a2ec1f3c9f176":{"id":"k-1f5a2ec1f3c9f176","mode":"k","type":"制度与规则","title":"以案促改促治","qs":[],"count":1},"k-a460727ca8a3699e":{"id":"k-a460727ca8a3699e","mode":"k","type":"制度与规则","title":"群众监督和舆论监督的“前哨”作用","qs":[],"count":1},"k-cbc9e0669b3200e8":{"id":"k-cbc9e0669b3200e8","mode":"k","type":"制度与规则","title":"完善党和国家监督制度","qs":[],"count":1},"k-16f3b707864928dd":{"id":"k-16f3b707864928dd","mode":"k","type":"制度与规则","title":"严管厚爱与“三个区分开来”","qs":[],"count":1},"k-522c911507a1db27":{"id":"k-522c911507a1db27","mode":"k","type":"观点与论证","title":"党的力量来自组织，组织强则军队强","qs":[],"count":1},"k-b2e8968d79ac7287":{"id":"k-b2e8968d79ac7287","mode":"k","type":"制度与规则","title":"军队党的建设围绕能打仗、打胜仗展开","qs":[],"count":1},"k-9ebda3c13218d4b5":{"id":"k-9ebda3c13218d4b5","mode":"k","type":"观点与论证","title":"选人用人的导向作用","qs":[],"count":1},"k-f0fe2b99668b4de3":{"id":"k-f0fe2b99668b4de3","mode":"k","type":"制度与规则","title":"以改革创新激发军队人才队伍活力","qs":[],"count":1}},"questions":{}};
